/* ---- Design tokens ------------------------------------------------------- */
:root {
  --font: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --radius: 12px;
  --radius-sm: 8px;
  --maxw: 1200px;

  --bg: #f6f7f9;
  --surface: #ffffff;
  --surface-2: #f0f2f5;
  --border: #e2e5ea;
  --border-strong: #cfd4dc;
  --text: #1a1d24;
  --text-2: #565d6b;
  --text-3: #8a92a1;
  --accent: #3b5bfd;
  --accent-weak: #eaeeff;
  --danger: #d64545;
  --danger-weak: #fdeaea;
  --shadow: 0 1px 2px rgba(20, 24, 40, 0.06), 0 4px 16px rgba(20, 24, 40, 0.06);
  --shadow-lg: 0 12px 40px rgba(20, 24, 40, 0.18);
}

:root[data-theme="dark"] {
  --bg: #0f1115;
  --surface: #181b22;
  --surface-2: #21252e;
  --border: #2a2f3a;
  --border-strong: #3a414f;
  --text: #eceef2;
  --text-2: #a9b1bf;
  --text-3: #6f7889;
  --accent: #6f86ff;
  --accent-weak: #1e243b;
  --danger: #f26d6d;
  --danger-weak: #35211f;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 6px 20px rgba(0, 0, 0, 0.35);
  --shadow-lg: 0 16px 48px rgba(0, 0, 0, 0.55);
}

@media (prefers-color-scheme: dark) {
  :root[data-theme="auto"] {
    --bg: #0f1115; --surface: #181b22; --surface-2: #21252e;
    --border: #2a2f3a; --border-strong: #3a414f;
    --text: #eceef2; --text-2: #a9b1bf; --text-3: #6f7889;
    --accent: #6f86ff; --accent-weak: #1e243b;
    --danger: #f26d6d; --danger-weak: #35211f;
    --shadow: 0 1px 2px rgba(0,0,0,.3), 0 6px 20px rgba(0,0,0,.35);
    --shadow-lg: 0 16px 48px rgba(0,0,0,.55);
  }
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  font-size: 15px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}
button { font-family: inherit; cursor: pointer; }
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }

/* ---- Layout -------------------------------------------------------------- */
.app { display: grid; grid-template-columns: 260px 1fr; min-height: 100vh; }

.sidebar {
  background: var(--surface);
  border-right: 1px solid var(--border);
  padding: 20px 16px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  position: sticky;
  top: 0;
  height: 100vh;
  overflow-y: auto;
}
.brand { display: flex; align-items: center; gap: 10px; font-weight: 700; font-size: 18px; }
.brand-mark { color: var(--accent); }

.add-btn { width: 100%; justify-content: center; font-weight: 600; }
.plus { font-size: 18px; line-height: 1; }

.nav { display: flex; flex-direction: column; gap: 2px; }
.nav-item {
  display: flex; justify-content: space-between; align-items: center;
  background: none; border: none; color: var(--text-2);
  padding: 9px 12px; border-radius: var(--radius-sm); font-size: 14px;
  font-weight: 500; text-align: left;
}
.nav-item:hover { background: var(--surface-2); color: var(--text); }
.nav-item.active { background: var(--accent-weak); color: var(--accent); }
.nav-count {
  font-size: 12px; color: var(--text-3);
  background: var(--surface-2); padding: 1px 8px; border-radius: 20px; font-weight: 600;
}
.nav-item.active .nav-count { background: var(--surface); color: var(--accent); }

.nav-section-head {
  font-size: 11px; text-transform: uppercase; letter-spacing: .06em;
  color: var(--text-3); font-weight: 700; margin: 0 8px 8px; padding-top: 4px;
}
.saved-filters, .tag-cloud { display: flex; flex-direction: column; gap: 2px; }
.saved-filter {
  display: flex; justify-content: space-between; align-items: center;
  padding: 7px 12px; border-radius: var(--radius-sm); font-size: 13px; color: var(--text-2);
}
.saved-filter:hover { background: var(--surface-2); }
.saved-filter span:first-child { cursor: pointer; flex: 1; }
.saved-filter .del { opacity: 0; border: none; background: none; color: var(--text-3); font-size: 14px; }
.saved-filter:hover .del { opacity: 1; }
.saved-filter .del:hover { color: var(--danger); }

.tag-cloud { flex-direction: row; flex-wrap: wrap; gap: 6px; padding: 0 4px; }
.tag-chip {
  font-size: 12px; padding: 3px 10px; border-radius: 20px;
  background: var(--surface-2); color: var(--text-2); border: 1px solid transparent;
}
.tag-chip:hover { border-color: var(--border-strong); color: var(--text); }
.tag-chip .c { color: var(--text-3); margin-left: 5px; }

.sidebar-footer { margin-top: auto; display: flex; flex-direction: column; gap: 4px; padding-top: 8px; border-top: 1px solid var(--border); }
.link-btn { background: none; border: none; color: var(--text-2); text-align: left; padding: 8px 12px; border-radius: var(--radius-sm); font-size: 13px; }
.link-btn:hover { background: var(--surface-2); color: var(--text); }

/* ---- Main --------------------------------------------------------------- */
.main { padding: 24px 32px 64px; max-width: var(--maxw); width: 100%; }

.topbar { display: flex; gap: 16px; align-items: center; margin-bottom: 18px; flex-wrap: wrap; }
.search-wrap { flex: 1; min-width: 280px; position: relative; display: flex; align-items: center; }
.search {
  flex: 1; padding: 11px 90px 11px 16px; border-radius: var(--radius);
  border: 1px solid var(--border); background: var(--surface); color: var(--text);
  font-size: 14px; box-shadow: var(--shadow);
}
.search:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-weak); }
.ghost-btn {
  background: none; border: none; color: var(--text-2); font-size: 13px; font-weight: 500;
  padding: 6px 10px; border-radius: var(--radius-sm);
}
.ghost-btn:hover { background: var(--surface-2); color: var(--text); }
#save-filter-btn { position: absolute; right: 6px; }

.toolbar { display: flex; align-items: center; gap: 12px; }
.sort-label { font-size: 13px; color: var(--text-3); display: flex; align-items: center; gap: 6px; }
select {
  font-family: inherit; font-size: 13px; padding: 8px 10px; border-radius: var(--radius-sm);
  border: 1px solid var(--border); background: var(--surface); color: var(--text);
}
.view-toggle { display: flex; border: 1px solid var(--border); border-radius: var(--radius-sm); overflow: hidden; }
.view-toggle button { background: var(--surface); border: none; padding: 8px 12px; color: var(--text-3); font-size: 15px; }
.view-toggle button.active { background: var(--accent-weak); color: var(--accent); }

.result-meta { display: flex; align-items: center; gap: 16px; margin-bottom: 14px; }
.select-all-wrap { font-size: 13px; color: var(--text-2); display: flex; align-items: center; gap: 7px; }
.muted { color: var(--text-3); font-size: 13px; }

/* ---- Bulk bar ----------------------------------------------------------- */
.bulk-bar {
  display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
  background: var(--surface); border: 1px solid var(--border-strong);
  border-radius: var(--radius); padding: 10px 16px; margin-bottom: 14px; box-shadow: var(--shadow);
}
.bulk-count { font-weight: 600; font-size: 13px; }
.bulk-actions { display: flex; gap: 6px; flex-wrap: wrap; }
.bulk-actions button {
  background: var(--surface-2); border: 1px solid var(--border); color: var(--text-2);
  padding: 6px 12px; border-radius: var(--radius-sm); font-size: 13px; font-weight: 500;
}
.bulk-actions button:hover { background: var(--accent-weak); color: var(--accent); border-color: var(--accent); }
.bulk-actions button.danger:hover { background: var(--danger-weak); color: var(--danger); border-color: var(--danger); }
#bulk-clear { margin-left: auto; }

/* ---- Cards -------------------------------------------------------------- */
.cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 18px; }
.cards.list { grid-template-columns: 1fr; gap: 10px; }

.card {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  overflow: hidden; display: flex; flex-direction: column; box-shadow: var(--shadow);
  transition: transform .12s ease, box-shadow .12s ease, border-color .12s ease; position: relative;
}
.card:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); border-color: var(--border-strong); }
.card.selected { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-weak); }

.card-select { position: absolute; top: 12px; left: 12px; z-index: 2; }
.card-select input { width: 17px; height: 17px; cursor: pointer; accent-color: var(--accent); }

.card-preview {
  aspect-ratio: 16 / 9; background: var(--surface-2); display: block;
  object-fit: cover; width: 100%; border-bottom: 1px solid var(--border);
}
.card-preview.placeholder {
  display: flex; align-items: center; justify-content: center; color: var(--text-3);
  font-size: 32px; font-weight: 700;
}

.card-body { padding: 14px 16px 16px; display: flex; flex-direction: column; gap: 8px; flex: 1; }
.card-site { display: flex; align-items: center; gap: 7px; font-size: 12px; color: var(--text-3); }
.card-favicon { width: 16px; height: 16px; border-radius: 4px; object-fit: cover; flex-shrink: 0; }
.card-title { font-weight: 600; font-size: 15.5px; line-height: 1.35; color: var(--text); }
.card-title a { color: inherit; }
.card-desc { font-size: 13.5px; color: var(--text-2); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }

.card-tags { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 2px; }
.card-tag { font-size: 11.5px; background: var(--surface-2); color: var(--text-2); padding: 2px 9px; border-radius: 20px; cursor: pointer; }
.card-tag:hover { background: var(--accent-weak); color: var(--accent); }

.card-note { font-size: 12.5px; color: var(--text-2); background: var(--surface-2); padding: 8px 10px; border-radius: var(--radius-sm); border-left: 3px solid var(--accent); }

.card-foot { display: flex; align-items: center; gap: 4px; margin-top: auto; padding-top: 6px; }
.card-badges { display: flex; gap: 6px; flex-wrap: wrap; margin-right: auto; }
.badge { font-size: 11px; font-weight: 600; padding: 2px 8px; border-radius: 20px; }
.badge.read { background: var(--accent-weak); color: var(--accent); }
.badge.snap { background: var(--surface-2); color: var(--text-2); }
.icon-btn {
  border: none; background: none; color: var(--text-3); font-size: 15px; padding: 6px;
  border-radius: var(--radius-sm); line-height: 1;
}
.icon-btn:hover { background: var(--surface-2); color: var(--text); }
.icon-btn.on { color: var(--accent); }

/* list view tweaks */
.cards.list .card { flex-direction: row; align-items: stretch; }
.cards.list .card-preview { width: 160px; aspect-ratio: auto; border-bottom: none; border-right: 1px solid var(--border); flex-shrink: 0; }
.cards.list .card-preview.placeholder { font-size: 24px; }
.cards.list .card-body { flex: 1; }
.compact .card-desc { -webkit-line-clamp: 2; }
.compact .card-preview { aspect-ratio: 21 / 9; }

/* ---- Empty state -------------------------------------------------------- */
.empty { text-align: center; padding: 80px 20px; color: var(--text-3); }
.empty h3 { color: var(--text-2); font-weight: 600; margin: 0 0 8px; }

/* ---- Buttons ------------------------------------------------------------ */
.btn {
  display: inline-flex; align-items: center; gap: 8px; border: 1px solid var(--border);
  background: var(--surface); color: var(--text); padding: 10px 16px; border-radius: var(--radius-sm);
  font-size: 14px; font-weight: 500;
}
.btn:hover { background: var(--surface-2); }
.btn-primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn-primary:hover { background: var(--accent); filter: brightness(1.07); }
.btn-danger { background: var(--danger); border-color: var(--danger); color: #fff; }
.btn-ghost { background: none; }

/* ---- Modal -------------------------------------------------------------- */
.overlay {
  position: fixed; inset: 0; background: rgba(15, 17, 21, 0.5);
  display: flex; align-items: flex-start; justify-content: center;
  padding: 48px 16px; z-index: 100; overflow-y: auto; backdrop-filter: blur(2px);
}
.modal {
  background: var(--surface); border-radius: var(--radius); width: 100%; max-width: 620px;
  box-shadow: var(--shadow-lg); border: 1px solid var(--border); animation: pop .14s ease;
