}
.card:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); border-color: var(--border-strong); }
.card.selected { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-weak); }

.card-select { position: absolute; top: 12px; left: 12px; z-index: 2; }
.card-select input { width: 17px; height: 17px; cursor: pointer; accent-color: var(--accent); }

.card-preview {
