import("playwright").then(async ({chromium}) => {
  const b = await chromium.launch({args:["--no-sandbox"]});
  const p = await b.newPage();
  await p.goto("http://127.0.0.1:4010/", {waitUntil:"networkidle"});
  await p.waitForSelector("#app[data-harness-ready=\"true\"]");
  // Open add modal
  await p.click("#add-btn");
  await p.waitForSelector("#f-url");
  await p.fill("#f-url", "https://www.iana.org/help/example-domains");
  await p.click("#f-title"); // trigger blur on url -> autofetch
  await p.waitForFunction(() => { const h=document.querySelector("#fetch-hint"); return h && !h.querySelector(".spinner") && h.textContent.length>0; }, {timeout:15000});
